style.css:
@-moz-document domain("login.k12.com") {
/* General Background */
    body {
        background-color: #ffe6f0; /* Light pink */
        background-image: url('https://i.pinimg.com/originals/88/ba/9b/88ba9b72f0df4fa9c7024085e217fe5d.jpg'); /* Hello Kitty pastel background */
        background-size: cover;
        background-attachment: fixed;
        font-family: "Comic Sans MS", "Poppins", sans-serif;
        color: #ff5fa2; /* Hello Kitty pink font color */
    }

    /* Headers and Titles */
    h1, h2, h3, h4, h5 {
        font-family: "Poppins", sans-serif;
        color: #ff3366; /* Bright pink for emphasis */
        text-shadow: 2px 2px #ffffff;
    }

    /* Links */
    a {
        color: #ff66b3; /* Light pink links */
        text-decoration: none;
    }

    a:hover {
        color: #ff99cc; /* Softer pink on hover */
        text-decoration: underline;
    }

    /* Buttons */
    button, input[type="submit"] {
        background-color: #ff99cc; /* Light pink button background */
        border: 2px solid #ff5fa2; /* Pink border */
        color: white;
        font-weight: bold;
        border-radius: 20px;
        box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.1);
        padding: 10px 20px;
        cursor: pointer;
        transition: transform 0.3s ease, background-color 0.3s ease;
    }

    button:hover, input[type="submit"]:hover {
        background-color: #ff5fa2; /* Darker pink on hover */
        transform: scale(1.1); /* Slight grow effect */
    }

    /* Inputs (Text, Password) */
    input[type="text"], input[type="password"] {
        background-color: #fff0f5; /* Soft pastel pink */
        border: 2px solid #ffb6c1; /* Soft pink border */
        border-radius: 10px;
        padding: 10px;
        color: #ff3366; /* Pink text */
        font-family: "Comic Sans MS", sans-serif;
    }

    input[type="text"]:focus, input[type="password"]:focus {
        outline: none;
        border-color: #ff66b3; /* Highlight on focus */
        box-shadow: 0px 0px 8px #ff99cc;
    }

    /* Navbar */
    .navbar, header {
        background-color: #ffccf2; /* Lighter pink for the header */
        border-bottom: 3px solid #ff99cc;
        box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
    }

    /* Footer */
    footer {
        background-color: #ffe6f0; /* Matching background color */
        color: #ff5fa2;
        font-size: 12px;
        text-align: center;
        padding: 10px;
    }

    /* Hello Kitty Icon on Login Form */
    .login-form::before {
        content: url('https://i.pinimg.com/originals/1b/1d/13/1b1d13b4307d2283698234b2b6d7d8e0.png'); /* Hello Kitty icon */
        display: block;
        margin: 0 auto 20px auto;
        width: 100px;
        height: auto;
    }

    /* Custom Scrollbar */
    ::-webkit-scrollbar {
        width: 8px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #ff99cc; /* Pink scroll thumb */
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background-color: #ffe6f0; /* Light pink track */
    }
}
